/** static void LoadBagItemListBuffers(u8 pocketId) */
export function LoadBagItemListBuffers(pocketId: any): any {
  let i: any = null;
      let pocket: any =gBagPockets[pocketId];
      let subBuffer: any = null;

      if (!gBagMenu.hideCloseBagText)
      {
          for (i = 0; i < gBagMenu.numItemStacks[pocketId] - 1; i++)
          {
              GetItemNameFromPocket(sListBuffer2.name[i], pocket.itemSlots[i].itemId);
              subBuffer = sListBuffer1.subBuffers;
              subBuffer[i].name = sListBuffer2.name[i];
              subBuffer[i].id = i;
          }
          StringCopy(sListBuffer2.name[i], gText_CloseBag);
          subBuffer = sListBuffer1.subBuffers;
          subBuffer[i].name = sListBuffer2.name[i];
          subBuffer[i].id = LIST_CANCEL;
      }
      else
      {
          for (i = 0; i < gBagMenu.numItemStacks[pocketId]; i++)
          {
              GetItemNameFromPocket(sListBuffer2.name[i], pocket.itemSlots[i].itemId);
              subBuffer = sListBuffer1.subBuffers;
              subBuffer[i].name = sListBuffer2.name[i];
              subBuffer[i].id = i;
          }
      }
      gMultiuseListMenuTemplate = sItemListMenu;
      gMultiuseListMenuTemplate.totalItems = gBagMenu.numItemStacks[pocketId];
      gMultiuseListMenuTemplate.items = sListBuffer1.subBuffers;
      gMultiuseListMenuTemplate.maxShowed = gBagMenu.numShownItems[pocketId];
}

/** static void GetItemNameFromPocket(u8 *dest, u16 itemId) */
export function GetItemNameFromPocket(dest: any, itemId: any): any {
  switch (gBagPosition.pocket)
      {
      case TMHM_POCKET:
          StringCopy(gStringVar2, gMoveNames[ItemIdToBattleMoveId(itemId)]);
          if (itemId >= ITEM_HM01)
          {
               
              ConvertIntToDecimalStringN(gStringVar1, itemId - ITEM_HM01 + 1, STR_CONV_MODE_LEADING_ZEROS, 1);
              StringExpandPlaceholders(dest, gText_NumberItem_HM);
          }
          else
          {
               
              ConvertIntToDecimalStringN(gStringVar1, itemId - ITEM_TM01 + 1, STR_CONV_MODE_LEADING_ZEROS, 2);
              StringExpandPlaceholders(dest, gText_NumberItem_TMBerry);
          }
          break;
      case BERRIES_POCKET:
          ConvertIntToDecimalStringN(gStringVar1, itemId - FIRST_BERRY_INDEX + 1, STR_CONV_MODE_LEADING_ZEROS, 2);
          CopyItemName(itemId, gStringVar2);
          StringExpandPlaceholders(dest, gText_NumberItem_TMBerry);
          break;
      default:
          CopyItemName(itemId, dest);
          break;
      }
}

/** static void BagMenu_MoveCursorCallback(s32 itemIndex, bool8 onInit, struct ListMenu *list) */
export function BagMenu_MoveCursorCallback(itemIndex: any, onInit: any, list: any): any {
  if (onInit != TRUE)
      {
          PlaySE(SE_SELECT);
          ShakeBagSprite();
      }
      if (gBagMenu.toSwapPos == NOT_SWAPPING)
      {
          RemoveBagItemIconSprite(gBagMenu.itemIconSlot ^ 1);
          if (itemIndex != LIST_CANCEL)
             AddBagItemIconSprite(BagGetItemIdByPocketPosition(gBagPosition.pocket + 1, itemIndex), gBagMenu.itemIconSlot);
          else
             AddBagItemIconSprite(ITEM_LIST_END, gBagMenu.itemIconSlot);
          gBagMenu.itemIconSlot ^= 1;
          if (!gBagMenu.inhibitItemDescriptionPrint)
              PrintItemDescription(itemIndex);
      }
}

/** static void BagMenu_ItemPrintCallback(u8 windowId, u32 itemIndex, u8 y) */
export function BagMenu_ItemPrintCallback(windowId: any, itemIndex: any, y: any): any {
  let itemId: any = null;
      let itemQuantity: any = null;
      let offset: any = null;

      if (itemIndex != LIST_CANCEL)
      {
          if (gBagMenu.toSwapPos != NOT_SWAPPING)
          {
               
              if (gBagMenu.toSwapPos == itemIndex)
                  BagMenu_PrintCursorAtPos(y, COLORID_GRAY_CURSOR);
              else
                  BagMenu_PrintCursorAtPos(y, COLORID_NONE);
          }

          itemId = BagGetItemIdByPocketPosition(gBagPosition.pocket + 1, itemIndex);
          itemQuantity = BagGetQuantityByPocketPosition(gBagPosition.pocket + 1, itemIndex);

           
          if (itemId >= ITEM_HM01 && itemId <= ITEM_HM08)
              BlitBitmapToWindow(windowId, gBagMenuHMIcon_Gfx, 8, y - 1, 16, 16);

          if (gBagPosition.pocket == BERRIES_POCKET)
          {
               
              ConvertIntToDecimalStringN(gStringVar1, itemQuantity, STR_CONV_MODE_RIGHT_ALIGN, BERRY_CAPACITY_DIGITS);
              StringExpandPlaceholders(gStringVar4, gText_xVar1);
              offset = GetStringRightAlignXOffset(FONT_NARROW, gStringVar4, 119);
              BagMenu_Print(windowId, FONT_NARROW, gStringVar4, offset, y, 0, 0, TEXT_SKIP_DRAW, COLORID_NORMAL);
          }
          else if (gBagPosition.pocket != KEYITEMS_POCKET && GetItemImportance(itemId) == FALSE)
          {
               
              ConvertIntToDecimalStringN(gStringVar1, itemQuantity, STR_CONV_MODE_RIGHT_ALIGN, BAG_ITEM_CAPACITY_DIGITS);
              StringExpandPlaceholders(gStringVar4, gText_xVar1);
              offset = GetStringRightAlignXOffset(FONT_NARROW, gStringVar4, 119);
              BagMenu_Print(windowId, FONT_NARROW, gStringVar4, offset, y, 0, 0, TEXT_SKIP_DRAW, COLORID_NORMAL);
          }
          else
          {
               
              if (gSaveBlock1Ptr.registeredItem != ITEM_NONE && gSaveBlock1Ptr.registeredItem == itemId)
                  BlitBitmapToWindow(windowId, sRegisteredSelect_Gfx, 96, y - 1, 24, 16);
          }
      }
}

