/** static void PrepareBagForWallyTutorial(void) */
export function PrepareBagForWallyTutorial(): any {
  let i: any = null;

      sTempWallyBag = AllocZeroed(0);
      memcpy(sTempWallyBag.bagPocket_Items, gSaveBlock1Ptr.bagPocket_Items, sizeof(gSaveBlock1Ptr.bagPocket_Items));
      memcpy(sTempWallyBag.bagPocket_PokeBalls, gSaveBlock1Ptr.bagPocket_PokeBalls, sizeof(gSaveBlock1Ptr.bagPocket_PokeBalls));
      sTempWallyBag.pocket = gBagPosition.pocket;
      for (i = 0; i < POCKETS_COUNT; i++)
      {
          sTempWallyBag.cursorPosition[i] = gBagPosition.cursorPosition[i];
          sTempWallyBag.scrollPosition[i] = gBagPosition.scrollPosition[i];
      }
      ClearItemSlots(gSaveBlock1Ptr.bagPocket_Items, BAG_ITEMS_COUNT);
      ClearItemSlots(gSaveBlock1Ptr.bagPocket_PokeBalls, BAG_POKEBALLS_COUNT);
      ResetBagScrollPositions();
}

/** static void RestoreBagAfterWallyTutorial(void) */
export function RestoreBagAfterWallyTutorial(): any {
  let i: any = null;

      memcpy(gSaveBlock1Ptr.bagPocket_Items, sTempWallyBag.bagPocket_Items, sizeof(sTempWallyBag.bagPocket_Items));
      memcpy(gSaveBlock1Ptr.bagPocket_PokeBalls, sTempWallyBag.bagPocket_PokeBalls, sizeof(sTempWallyBag.bagPocket_PokeBalls));
      gBagPosition.pocket = sTempWallyBag.pocket;
      for (i = 0; i < POCKETS_COUNT; i++)
      {
          gBagPosition.cursorPosition[i] = sTempWallyBag.cursorPosition[i];
          gBagPosition.scrollPosition[i] = sTempWallyBag.scrollPosition[i];
      }
      Free(sTempWallyBag);
}

/** void DoWallyTutorialBagMenu(void) */
export function DoWallyTutorialBagMenu(): any {
  PrepareBagForWallyTutorial();
      AddBagItem(ITEM_POTION, 1);
      AddBagItem(ITEM_POKE_BALL, 1);
      GoToBagMenu(ITEMMENULOCATION_WALLY, ITEMS_POCKET, CB2_SetUpReshowBattleScreenAfterMenu2);
}

/** static void Task_WallyTutorialBagMenu(u8 taskId) */
export function Task_WallyTutorialBagMenu(taskId: any): any {
  let data: any = gTasks[taskId].data;

      if (!gPaletteFade.active)
      {
          switch (tTimer)
          {
          case WALLY_BAG_DELAY * 1:
              PlaySE(SE_SELECT);
              SwitchBagPocket(taskId, MENU_CURSOR_DELTA_RIGHT, FALSE);
              tTimer++;
              break;
          case WALLY_BAG_DELAY * 2:
              PlaySE(SE_SELECT);
              BagMenu_PrintCursor(tListTaskId, COLORID_GRAY_CURSOR);
              gSpecialVar_ItemId = ITEM_POKE_BALL;
              OpenContextMenu(taskId);
              tTimer++;
              break;
          case WALLY_BAG_DELAY * 3:
              PlaySE(SE_SELECT);
              RemoveContextWindow();
              DestroyListMenuTask(tListTaskId, 0, 0);
              RestoreBagAfterWallyTutorial();
              Task_FadeAndCloseBagMenu(taskId);
              break;
          default:
              tTimer++;
              break;
          }
      }
}

